                # Normalize angle to be between 0 and 2*pi
                angle = (angle + 2 * pi) % (2 * pi)

                # Calculate the angle of pk relative to p2
                angle2 = angle_from_origin((pk[0] - p2[0], pk[1] - p2[1]))
                angle2 = (angle2 + 2 * pi) % (2 * pi)

                # Check if pk is on the line segment p1p2
