        return isclose((px - cx) ** 2 + (py - cy) ** 2, r ** 2)

    def is_between(a, b, c):
        # Check if point c is between a and b on the line segment ab
        return (min(a[0], b[0]) <= c[0] <= max(a[0], b[0]) and
                min(a[1], b[1]) <= c[1] <= max(a[1], b[1]))

    def line_intersects_circle(a, b, cx, cy, r=1.0):
        # Check if line segment ab intersects the circle centered at (cx, cy) with radius r
        if is_on_circle(a[0], a[1], cx, cy, r) or is_on_circle(b[0], b[1], cx, cy, r):
            return True
        # Check if the line segment ab crosses the circle
        ac = (cx - a[0], cy - a[1])
        ab = (b[0] - a[0], b[1] - a[1])
        ab2 = ab[0] ** 2 + ab[1] ** 2
        acab = ac[0] * ab[0] + ac[1] * ab[1]
        t = acab / ab2 if ab2 != 0 else -1
        if t < 0 or t > 1:
            return False
        closest_x = a[0] + t * ab[0]
        closest_y = a[1] + t * ab[1]
        return is_on_circle(closest_x, closest_y, cx, cy, r)

    max_slices = 0
